using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
public static class ProbeArtArchitecture{
 public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Idle");for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Dirty");var setup=EditorSceneManager.GetSceneManagerSetup();var rows=new List<object>();try{foreach(var name in new[]{"Jamsil","ShoeTower"}){var s=EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/"+name+".unity");var d=Object.FindFirstObjectByType<Chapter45Director>();var sc=d.transform.Find("Scenery");rows.Add(Json(new{scene=name,roots=sc.Cast<Transform>().Select(t=>new{t.name,p=t.position.ToString("R"),size=t.GetComponentsInChildren<Renderer>(true).Length}),towers=sc.GetComponentsInChildren<MeshRenderer>(true).Where(r=>(r.name.ToLower().Contains("tower")||r.name.ToLower().Contains("facade")||r.name.ToLower().Contains("building"))&&r.bounds.size.y>12).Select(r=>new{path=PathOf(r.transform),pos=r.transform.position.ToString("R"),scale=r.transform.lossyScale.ToString("R"),min=r.bounds.min.ToString("R"),max=r.bounds.max.ToString("R"),materials=r.sharedMaterials.Select(m=>AssetDatabase.GetAssetPath(m)),mesh=AssetDatabase.GetAssetPath(r.GetComponent<MeshFilter>()?.sharedMesh)}),entry=sc.GetComponentsInChildren<Transform>(true).Where(t=>t.name.Contains("Entrance")||t.name.Contains("Entry")||t.name.Contains("Podium")).Take(25).Select(t=>new{path=PathOf(t),pos=t.position.ToString("R"),scale=t.lossyScale.ToString("R")})}));}}finally{EditorSceneManager.RestoreSceneManagerSetup(setup);}string o="outputs/department-store-2026-10-02/trellis-recovery/architecture-probe-20261003.json";File.WriteAllText(o,"["+string.Join(",",rows.Cast<string>())+"]");return o;}
 static string Json(object v)=>(string)AppDomain.CurrentDomain.GetAssemblies().First(a=>a.GetName().Name=="Newtonsoft.Json").GetType("Newtonsoft.Json.JsonConvert").GetMethod("SerializeObject",new[]{typeof(object)}).Invoke(null,new[]{v});
 static string PathOf(Transform t)=>t.parent==null?t.name:PathOf(t.parent)+"/"+t.name;
}
